#!/usr/bin/env bash
# Build one libxml2 version into a fuzzer binary with SanitizerCoverage.
#
#   ./build.sh 2.14.6
#
# Produces build/<version>/: fredbear (the fuzzer), xml.dict, seeds/ (generated by the tag's own
# fuzz/genSeed from its test files, as OSS-Fuzz does). The harness is the tag's own fuzz/xml.c
# (libxml2's OSS-Fuzz "xml" target); pick transitions where fuzz/xml.c, fuzz/fuzz.c, fuzz/fuzz.h
# and fuzz/xml.dict are unchanged so only the library differs.
#
# Same configuration as the tag's fuzz/oss-fuzz-build.sh, except --without-lzma (no liblzma
# headers on FarmShare). The harness's custom mutator is linked but never called: fredbear uses
# its own operator families (see ../harness_shim.c).
set -euo pipefail

VERSION=${1:?usage: build.sh <version, e.g. 2.14.6>}
HERE=$(cd "$(dirname "$0")" && pwd)
FUZZER=$(cd "$HERE/../.." && pwd)
REPO=$HERE/repo
OUT=$HERE/build/$VERSION
JOBS=${SLURM_CPUS_PER_TASK:-4}

[ -d "$REPO" ] || git clone -q https://gitlab.gnome.org/GNOME/libxml2.git "$REPO"
if ! git -C "$REPO" rev-parse -q --verify "refs/tags/v$VERSION" >/dev/null; then
    echo "error: no tag v$VERSION in $REPO" >&2
    exit 1
fi

rm -rf "$OUT"
mkdir -p "$OUT/src" "$OUT/obj" "$OUT/seeds"
git -C "$REPO" archive "v$VERSION" | tar -x -C "$OUT/src"
SRC=$OUT/src
FLAGS="-O1 -g -fsanitize-coverage=trace-pc-guard"

# Library: static, instrumented.
(
    cd "$SRC"
    NOCONFIGURE=1 ./autogen.sh >/dev/null 2>&1
    CC=clang CFLAGS="$FLAGS" ./configure -q \
        --disable-shared --without-debug --without-http --without-python \
        --with-zlib --without-lzma >/dev/null
    make -s -j"$JOBS" libxml2.la >/dev/null
)

# Harness objects, instrumented like the library (OSS-Fuzz instruments them too).
INC="-I$SRC/include -I$SRC"
clang $FLAGS $INC -c "$SRC/fuzz/fuzz.c" -o "$OUT/obj/fuzz.o"
clang $FLAGS $INC -c "$SRC/fuzz/xml.c" -o "$OUT/obj/xml.o"
clang -O1 -c "$HERE/../harness_shim.c" -o "$OUT/obj/harness_shim.o"
(cd "$OUT/obj" && ar x "$SRC/.libs/libxml2.a")
ar rcs "$OUT/libharness.a" "$OUT"/obj/*.o

# Seeds: the tag's genSeed over the tag's XML_SEED_CORPUS_SRC list (fuzz/Makefile.am). genSeed
# links the instrumented library, so it gets no-op coverage callbacks.
cat > "$OUT/sancov_stub.c" <<'EOF'
#include <stdint.h>
void __sanitizer_cov_trace_pc_guard_init(uint32_t *start, uint32_t *stop) { (void) start; (void) stop; }
void __sanitizer_cov_trace_pc_guard(uint32_t *guard) { (void) guard; }
EOF
clang -O1 $INC "$SRC/fuzz/genSeed.c" "$OUT/obj/fuzz.o" "$OUT/sancov_stub.c" "$SRC/.libs/libxml2.a" \
    -lz -lm -o "$OUT/genSeed"
mapfile -t PATTERNS < <(sed -n '/^XML_SEED_CORPUS_SRC = /,/[^\\]$/p' "$SRC/fuzz/Makefile.am" |
    grep -o "'[^']*'" | tr -d "'" | sed 's|\$(top_srcdir)|..|')
(cd "$SRC/fuzz" && mkdir -p seed/xml && "$OUT/genSeed" xml "${PATTERNS[@]}" >/dev/null 2>&1)
cp "$SRC"/fuzz/seed/xml/* "$OUT/seeds/"
cp "$SRC/fuzz/xml.dict" "$OUT/"

# Relinks fuzzer/target/release/fredbear against this version; copy it out before building another.
(cd "$FUZZER" && FREDBEAR_HARNESS="$OUT/libharness.a" cargo build --release)
cp "$FUZZER/target/release/fredbear" "$OUT/fredbear"
echo "built $OUT/fredbear ($(ls "$OUT/seeds" | wc -l) seeds)"
